#!/usr/bin/env bash
# Kasbah VPN exit node — Ubuntu 22.04+/Debian 12+ VPS bootstrap.
#
# Run as root on a fresh VPS, paste the server .conf generated by
# `kasbah-vpn config server` into /etc/wireguard/kasbah0.conf, and the box
# becomes your personal exit node. Idempotent.
#
#   curl -fsSL <raw-url>/exit-node.sh | sudo bash
#   sudo nano /etc/wireguard/kasbah0.conf   # paste config
#   sudo systemctl enable --now wg-quick@kasbah0

set -euo pipefail

[ "$(id -u)" -eq 0 ] || { echo "run as root" >&2; exit 1; }

export DEBIAN_FRONTEND=noninteractive
apt-get update -q
apt-get install -qy wireguard wireguard-tools iptables

# Forwarding is required for exit-node routing.
cat > /etc/sysctl.d/99-kasbah-vpn.conf <<'EOF'
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1
EOF
sysctl --system > /dev/null

install -d -m 700 /etc/wireguard
if [ ! -f /etc/wireguard/kasbah0.conf ]; then
  cat > /etc/wireguard/kasbah0.conf <<'EOF'
# Paste the output of `kasbah-vpn config server` here, then:
#   systemctl enable --now wg-quick@kasbah0
EOF
  chmod 600 /etc/wireguard/kasbah0.conf
  echo "wrote placeholder /etc/wireguard/kasbah0.conf — paste your server config into it"
else
  echo "/etc/wireguard/kasbah0.conf already present — leaving it untouched"
fi

# Open the WireGuard port if ufw is active.
if command -v ufw > /dev/null && ufw status | grep -q "Status: active"; then
  ufw allow 51820/udp
fi

echo "done. after pasting the config: systemctl enable --now wg-quick@kasbah0"
